def durable_fds():
    candidates=os.listdir("/proc/self/fd"); durable=set()
    for entry in candidates:
        fd=int(entry)
        try: os.fstat(fd)
        except OSError: continue
        durable.add(fd)
    return durable
def close_to_keep(keep):
    for fd in durable_fds()-keep:
        try: os.close(fd)
        except OSError: pass
    if durable_fds()!=keep: fail("fd closure")

